contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address vault, address asset) public {
        uint256 firstRate;
        bool firstOk;

        try c.rate(vault, asset) returns (uint256 r) {
            firstRate = r;
            firstOk = true;
        } catch {
            firstOk = false;
        }

        uint256 balanceBefore = address(this).balance;

        uint256 secondRate;
        bool secondOk;

        try c.rate(vault, asset) returns (uint256 r2) {
            secondRate = r2;
            secondOk = true;
        } catch {
            secondOk = false;
        }

        // General rule: if the first rate call succeeds, the second one must also succeed
        // and rate never moves native currency, so the test contract's balance is unchanged.
        assert(!firstOk || (secondOk && address(this).balance == balanceBefore));
    }

    receive() external payable {}
}
